catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading)
        return;
    // Cleared (also after we clear an invalid date below): keep the error message visible
    if (!newValue)
        return;
    g_form.hideFieldMsg('due_date', true);

    // Request Date on a new request = today; same server-side check as the backend Client Script and Business Rule
    var ga = new GlideAjax('x_snp_manager_su_0.MgrHubAjax');
    ga.addParam('sysparm_name', 'getDueInfo');
    ga.addParam('sysparm_due_date', newValue);
    ga.getXMLAnswer(function(answer) {
        var info;
        try {
            info = JSON.parse(answer);
        } catch (e) {
            return; // the Business Rule still validates on submit
        }
        if (!info.valid) {
            g_form.clearValue('due_date');
            g_form.showFieldMsg('due_date', 'Due Date cannot be earlier than the Request Date (today).', 'error');
        }
    });
}
